-- Read-only follow-on quality checks and independent join-based counts.
with cats as(select id,name from communication_category where tenant_id='ff2df806-b321-4254-b651-3af11fccf1db' and id in ('814e0ba4-5afe-4e84-a502-81002ae34a93','683b3d0f-3136-4cc8-bb39-b50c9496d1e8')) select jsonb_build_object('observed_at',now(),'categories',(select jsonb_agg(x) from(select c.id,c.name,c.member_enabled,c.is_public,c.is_active,(select count(*) from communication_category_role r where r.category_id=c.id) role_assignments from communication_category c join cats on cats.id=c.id)x),'quality',(select jsonb_agg(x) from(select c.name,count(*) filter(where p.member_id is null) null_member_rows,count(*) filter(where p.member_id is not null and m.id is null) orphan_rows,count(*) filter(where m.id is not null and m.tenant_id is distinct from p.tenant_id) foreign_member_rows,count(*) filter(where p.tenant_id is distinct from 'ff2df806-b321-4254-b651-3af11fccf1db'::uuid) foreign_preference_rows from cats c join member_communication_preference p on p.category_id=c.id left join member m on m.id=p.member_id group by c.name)x),'duplicate_nonnull_pairs',(select count(*) from(select p.category_id,p.member_id from member_communication_preference p join cats c on c.id=p.category_id where p.member_id is not null group by 1,2 having count(*)>1)x),'external',(select jsonb_agg(x) from(select c.name,count(*) filter(where e.opted_out=false) active,count(*) filter(where e.opted_out=true) opted_out,count(*) filter(where e.opted_out is null) null_status,count(distinct lower(trim(e.email))) filter(where e.opted_out=false) distinct_active_emails,count(*) filter(where e.opted_out=false and exists(select 1 from member m where m.tenant_id=e.tenant_id and lower(trim(m.email))=lower(trim(e.email)))) member_email_overlap from cats c join email_subscriber e on e.communication_category_id=c.id and e.tenant_id='ff2df806-b321-4254-b651-3af11fccf1db' group by c.name)x),'independent_counts',(select jsonb_agg(x) from(select c.name,count(distinct m.id) n from cats c join member_communication_preference p on p.category_id=c.id and p.tenant_id='ff2df806-b321-4254-b651-3af11fccf1db' and p.is_subscribed=true join member m on m.id=p.member_id and m.tenant_id=p.tenant_id where coalesce(m.email,'')<>'' and m.email !~* '^deleted_.*@deleted[.]local$' and m.login_enabled is distinct from false and m.communications_opted_out_all is distinct from true group by c.name)x)) evidence;
